function n5ContextPosition(position){let value=String(position||'main character area').replace(/[-_]/g,' ');return value==='whole character'||value==='radical / main shape'?'main character area':value}
function n5ContextMeaning(record,ch){return record?.meanings?.[0]||N5_CONTEXT_MEMORY_SEEDS[ch]?.summary?.split(/[,:;]/)[0]||'study character'}
function n5ContextPart(glyph,position,ch,supplemental){let known=N5_CONTEXT_COMPONENT_GLOSSARY[glyph],partRecord=supplemental[glyph],n5Record=typeof N5_KANJI==='undefined'?null:N5_KANJI.find(item=>item.character===glyph),wordRecord=typeof N5_VOCAB==='undefined'?null:N5_VOCAB.find(item=>item.word===glyph),meaning=known?.[0]||partRecord?.meanings?.[0]||n5Record?.meanings?.[0]||wordRecord?.meanings?.[0],shape=known?.[1]||`the strokes grouped together as ${glyph}`,where=n5ContextPosition(position),label=meaning?`${glyph} · ${meaning}`:`Component ${glyph} · ${where}`,description=meaning?`This part is called ${glyph} and means ${meaning}. It sits at the ${where} of ${ch}. Picture ${shape}.`:`This shape is called ${glyph}; it sits at the ${where} of ${ch}. Look at its grouped strokes as one piece before reading the whole character.`;return {glyph,label,position:where,image:shape,description}}
function n5ContextFallbackParts(ch,record,supplemental){let parts=(record?.components||[]).slice(0,3).map(item=>n5ContextPart(item.ch,item.position,ch,supplemental));if(!parts.length){let radical=record?.radical||ch;parts.push(n5ContextPart(radical,'main area',ch,supplemental))}if(parts.length===1){let known=parts[0],position={top:'bottom half',bottom:'top half',left:'right half',right:'left half'}[known.position]||'remaining area';parts.push({glyph:ch,label:`Remaining strokes in ${ch}`,position,image:`the other strokes surrounding ${known.glyph}`,description:`These are the remaining strokes of ${ch}, around ${known.glyph}, in the ${position}. Look at them as a second piece next to ${known.label}.`})}if(parts.length>3)parts=parts.slice(0,3);return parts}
function n5ContextStory(ch,meaning,parts){let first=parts[0],second=parts[1],firstPosition=first.position||'first',secondPosition=second.position||'second',firstImage=first.image||first.glyph,secondImage=second.image||second.glyph,target=meaning.toLowerCase(),scene;if(/meet|meeting|gather|group/.test(target))scene=`Picture a person ${firstImage} meeting someone beneath ${secondImage}. The people gather there and turn the scene into “${meaning}.”`;else if(/bright|light|clear/.test(target))scene=`Imagine ${firstImage} and ${secondImage} shining together. Their light makes the scene feel “${meaning}.”`;else if(/blue|green|red|yellow|color/.test(target))scene=`Imagine ${firstImage} against a ${meaning} sky or object, with ${secondImage} completing the picture.`;else if(/brother|sister|family|child|person/.test(target))scene=`Imagine a family member shaped like ${firstImage} beside ${secondImage}; the scene helps you recall “${meaning}.”`;else if(/place|location|country|center|middle/.test(target))scene=`Imagine ${firstImage} marking a place and ${secondImage} showing what is there; together they make a picture of “${meaning}.”`;else if(/open|enter|inside|door/.test(target))scene=`Imagine ${firstImage} moving toward ${secondImage} and opening a way through; this scene points to “${meaning}.”`;else if(/go|walk|come|arrive|return|visit|call on/.test(target))scene=`Imagine following ${firstImage} toward ${secondImage} to ${meaning}; keep the movement in the picture.`;else if(/speak|say|word|language|voice/.test(target))scene=`Imagine ${firstImage} carrying words toward ${secondImage}; the message gives you a picture for “${meaning}.”`;else scene=`Imagine ${firstImage} at the ${firstPosition} and ${secondImage} at the ${secondPosition}. Let the two shapes interact in one small, memorable scene for “${meaning}.”`;return `For ${ch}, meaning “${meaning},” start at the ${firstPosition} with ${first.label}. Then look at the ${secondPosition} and find ${second.label}. ${scene} Trace the two parts in order and replay this picture when you see ${ch}.`}
function n5ContextExamples(ch,record,vocab,seed){let matches=vocab.filter(item=>item.level==='N5'&&item.word.includes(ch)&&item.reading&&item.meanings?.[0]).sort((a,b)=>Array.from(a.word).length-Array.from(b.word).length).slice(0,3).map(item=>({word:item.word,reading:item.reading,meaning:item.meanings[0]}));if(matches.length)return {words:matches,wordLabel:'Common words'};let seedWords=seed?.words;if(seedWords?.length)return {words:seedWords,wordLabel:'Example words'};let reading=(record?.kunyomi||[]).map(value=>value.replace(/[.-]/g,'')).find(Boolean)||(record?.onyomi||[])[0]||'reading shown in context',meaning=record?.meanings?.[0]||seed?.summary||'meaning shown in the study text';return {words:[{word:ch,reading,meaning}],wordLabel:'Representative reading'} }
function buildN5ContextMemoryCatalog(){let supplemental=globalThis.SAKURA_KANJI_SUPPLEMENTAL||{},catalog={...SAKURA_KANJI_MEMORY_BASE},vocab=typeof N5_VOCAB==='undefined'?[]:N5_VOCAB,sourceGroups=[vocab,typeof N5_GRAMMAR==='undefined'?[]:N5_GRAMMAR,typeof N5_READINGS==='undefined'?[]:N5_READINGS,typeof N5_STORIES==='undefined'?[]:N5_STORIES,typeof N5_COURSE_CONFIG==='undefined'?[]:N5_COURSE_CONFIG],characters=new Set(sourceGroups.flatMap(group=>[...JSON.stringify(group)].filter(char=>/\p{Script=Han}/u.test(char))));for(let ch of characters){if(catalog[ch])continue;let seed=N5_CONTEXT_MEMORY_SEEDS[ch],record=supplemental[ch],meaning=record?.meanings?.[0]||seed?.summary?.split(/[,:;]/)[0]||`character ${ch}`,parts=seed?.parts||n5ContextFallbackParts(ch,record,supplemental),examples=n5ContextExamples(ch,record,vocab,seed);while(parts.length<2)parts.push({glyph:ch,label:`${ch} · whole character`,position:'whole character',image:`the complete outline of ${ch}`,description:`This is the complete written form of ${ch}; notice how its strokes fit together.`});let summary=seed?.summary||`Look at ${parts[0].label} and ${parts[1].label} in ${ch}; use their positions and shapes to remember “${meaning}.”`,story=seed?.story||n5ContextStory(ch,meaning,parts);catalog[ch]={summary,parts,story,...examples}}return Object.freeze(catalog)}
globalThis.SAKURA_KANJI_MEMORY=buildN5ContextMemoryCatalog();
